      "narrative_section": "3. ST10 — Pallet conveyor"
    },
    {
      "name": "jam_time",
      "value": "5.0",
      "units": "s",
      "narrative_section": "3. ST10 — Pallet conveyor"
    }
  ],
  "steps": [
    {
      "name": "Running Conveyor",
      "entry": "Auto mode SS-0003 (X2) active, no ST10 fault (M199 inactive), and E-stop healthy (X0)",
      "exit": "Auto mode lost, ST10 fault/overload occurs, or E-stop lost"
    },
    {
      "name": "Pallet Release",
      "entry": "Release request RQ-1005 (X14) rising edge sets stopper solenoid XY-1004 (Y11)",
      "exit": "Release timer T11 reaches 2.0 s preset (resets Y11)"
    }
  ],
  "interlocks": [
    {
      "cause": "Motor overload MOL-1001 (X13 lost) or E-stop chain (X0 lost)",
      "effect": "Conveyor motor M-1001 (Y10) stops immediately via ST10 stop condition (M199)"
    },
    {
      "cause": "Auto mode SS-0003 (X2) OFF or ST10 common fault (M199) ON",
      "effect": "Conveyor motor M-1001 (Y10) is de-energised"
    }
  ],
  "alarms": [
    {
      "name": "Motor Overload",
      "condition": "Motor overload MOL-1001 contact open/lost (LDI X13)",
      "action": "Sets M191 overload alarm, raises M199 stop condition to shut down conveyor Y10"
    },
    {
      "name": "Pallet Jam",
      "condition": "Entry photo-eye PE-1002 stays blocked for more than 5.0 s while conveyor runs",
      "action": "Stops conveyor motor Y10 and raises jam alarm M190 until reset (X1)"
    }
  ],
  "conflicts": [
    {
      "item": "jam_detection_logic",
      "narrative_says": "If entry photo-eye PE-1002 stays blocked for more than 5.0 s while conveyor runs, conveyor stops and jam alarm is raised until reset",
      "parameter_sheet_says": "jam_time = 5.0 s, assigned to T10 (ST10)",
      "program_says": "R2 resets M190 and R3 reads M190, but there are no rungs implementing T10 timing or detecting PE-1002 blockage to SET M190",
      "authoritative": "parameter_sheet"
    },
    {
      "item": "e_stop_interlock_logic_R3",
      "narrative_says": "A motor overload or the E-stop chain stops the conveyor immediately (stopping conveyor when X0 is lost)",
      "parameter_sheet_says": "Not specified directly (X0 is defined as ES-0001 E-stop chain healthy)",
      "program_says": "R3 evaluates ORI X0 into M199, causing M199 to be ON (conveyor stopped) when E-stop is healthy (X0=1), and allowing M199 to clear when E-stop is dropped (X0=0)",
      "authoritative": "narrative"
    }
  ]
}
